func TestNewBindsEveryOperation(t *testing.T) {
	mock := New(t, "mock")
	if mock.QueryRecords().Definition().Operation.OperationID != "queryRecords" {
		t.Errorf("queryRecords mock has another definition")
	}
	if mock.GetRecord().Definition().Operation.OperationID != "getRecord" {
		t.Errorf("getRecord mock has another definition")
	}
	if mock.UpsertRecordByExternalID().Definition().Operation.OperationID != "upsertRecordByExternalId" {
		t.Errorf("upsertRecordByExternalId mock has another definition")
	}
	if mock.UpdateRecord().Definition().Operation.OperationID != "updateRecord" {
		t.Errorf("updateRecord mock has another definition")
	}
}
